return ['domain'=>'zinn-offload','plural-forms'=>'nplurals=4; plural=((((n >= 2 && n <= 4)) && ((0 == 0))) ? 1 : ((((0 == 0)) == 0)) ? 2 : (((n == 1)) && ((0 == 0))) ? 0 : 3);','language'=>'cs_CZ','project-id-version'=>'zinn-offload','pot-creation-date'=>'2026-09-06T10:05:56+00:00','po-revision-date'=>'2026-09-06T10:05:56+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Zinn® Media Offload'=>'Zinn® Media Offload','https://zinndigital.com/wordpress-plugins/zinn-offload'=>'https://zinndigital.com/wordpress-plugins/zinn-offload','Moves this site\'s media library to Zinn® object storage and serves it from a CDN. Configured from your Zinn® dashboard — no access key is ever typed into WordPress.'=>'Přesune knihovnu médií tohoto webu do objektového úložiště Zinn® a bude ji poskytovat z CDN. Konfiguruje se z vašeho řídicího panelu Zinn® – do WordPress se nezadává žádný přístupový klíč.','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','Zinn Digital® did not return a token. Nothing has been changed on this site.'=>'Zinn Digital® nevrátil token. Na tomto webu nebylo nic změněno.','That file could not be read from this server, so nothing was uploaded.'=>'Tento soubor nebylo možné z tohoto serveru přečíst, takže nebyl nahrán žádný obsah.','Storage refused the upload (HTTP %d). The file is still on this server.'=>'Úložisko odmietlo nahratie (HTTP %d). Súbor je stále na tomto serveri.','This site is no longer connected to Zinn® media offload. New uploads will stay on this server. Pair it again from your Zinn Digital® dashboard.'=>'Tento web již není připojen k offloadu médií Zinn®. Nová nahrávání zůstanou na tomto serveru. Spárujte jej znovu ze svého řídicího panelu Zinn Digital®.','Zinn Digital® answered with HTTP %d.'=>'Zinn Digital® odpověděl kódem HTTP %d.','Disconnected by Zinn Digital®.'=>'Odpojeno od Zinn Digital®.','%s — guides and services'=>'%s — průvodce a služby','User gui